  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C52"],
      "claim": "GSK1322322, which shares the anilino-pyrimidine and N-aryl piperazine core with the query, had absolute oral bioavailability of 77% in healthy volunteers, directly supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Linezolid, a polar drug with multiple hydrogen-bond acceptors, is ~100% orally bioavailable, demonstrating that high polarity/TPSA does not preclude high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Paliperidone, containing a basic piperidine and fused heteroaromatic lactam, has 28% absolute bioavailability in its ER form and ~100% in immediate-release form, both at or above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C56"],
      "claim": "Ketanserin, with a basic piperidine and polar heteroaromatic dione, has ~50% absolute bioavailability, supporting high F for a similarly ionizable and polar query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C51"],
      "claim": "Apalutamide, despite multiple aromatic heterocycles and hydrogen-bond acceptors, has ~100% absolute oral bioavailability, reinforcing that physicochemical priors alone are not decisive.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental analogues show absolute oral bioavailability at or above 20%, with several structurally related basic heteroaromatic drugs having F values of 28–100%. The physicochemical prior of low neutral fraction and high TPSA is outweighed by consistent, transferable experimental evidence, so the query is predicted to have high oral bioavailability at the F ≥ 20% threshold.",
  "evidence_gaps": [
    "No direct experimental bioavailability measurement exists for the query molecule.",
    "No specific data on intestinal permeability, efflux transport, or first-pass metabolism are available for the query.",
    "The query's low neutral fraction and high TPSA are uncertain physicochemical priors and could lower F in vivo, but no affirmative experimental evidence indicates F < 20%."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

